void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 10000;

    // Enhanced phase saving update with multiple strategies
    int phase_rand = rand() % 100;
    if (phase_rand < 60) {
        // Use local best phases (60% probability)
        for (int i = 1; i <= vars; i++) {
            saved[i] = local_best[i];
        }
    } else if (phase_rand < 80) {
        // Invert local best phases (20% probability)
        for (int i = 1; i <= vars; i++) {
            saved[i] = -local_best[i];
        }
    } else if (phase_rand < 90) {
        // Random phases (10% probability)
        for (int i = 1; i <= vars; i++) {
            saved[i] = rand() % 2 ? 1 : -1;
        }
    } else {
        // Current trail phases (10% probability)
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) {
                saved[i] = value[i];
            }
        }
    }
}
